      const handleChange = vi.fn();
      const { container } = render(
        <GridLayout colNum={12} compactType={ECompactType.NONE} layout={threeItemLayout()} margin={[10, 10]} multiSelect onLayoutChange={handleChange} ref={ref} rowHeight={100}>
