import { createRef } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import { ECompactType } from '@keystone-dashboard-layout/core';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import type { IGridLayoutHandle } from '../grid-layout-handle.interface';
import { dispatchDragEvent, dispatchResizeEvent } from './test-helpers';

describe(`GridLayout restoreOnDrag`, () => {
  it(`Should not let another item compact past its own pre-drag position while a drag is in progress`, () => {
    // A resting on top of B (A: y0-2, B: y2-4) — dragging A away should
    // normally let VERTICAL compaction immediately pull B up to y:0.
    // With restoreOnDrag on, B should stay at its own pre-drag y:2
    // throughout the drag (dragmove), not rise past it.
    const layout: TLayout = [
      { h: 2, i: `a`, w: 2, x: 0, y: 0 },
      { h: 2, i: `b`, w: 2, x: 0, y: 2 },
    ];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout layout={layout} margin={[10, 10]} onLayoutChange={handleChange} restoreOnDrag rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    dispatchDragEvent(target, `dragmove`, { clientX: 300, clientY: 0 });

    const midDragCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(midDragCall.find(entry => entry.i === `b`)!.y).toBe(2);
  });

  it(`Should let compaction resolve fully, unrestricted, via a later action that doesn't go through the drag path at all`, () => {
    // A second *drag* gesture wouldn't actually demonstrate this: with
    // restoreOnDrag still enabled for the whole grid, any later drag
    // re-snapshots whatever B's *current* position is at *that*
    // gesture's own dragstart, so B would stay restrained indefinitely
    // as long as something keeps being dragged — not because clearing
    // the snapshot at dragend failed, but because a fresh one is taken
    // immediately. `compactNow()` is a clean way to observe the
    // *unrestricted* case instead: it goes through
    // `commitForcedCompaction`, which never reads the drag-scoped
    // snapshot ref at all, regardless of `restoreOnDrag`.
    const ref = createRef<IGridLayoutHandle>();
    const layout: TLayout = [
      { h: 2, i: `a`, w: 2, x: 0, y: 0 },
      { h: 2, i: `b`, w: 2, x: 0, y: 2 },
    ];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout layout={layout} margin={[10, 10]} onLayoutChange={handleChange} ref={ref} restoreOnDrag rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    dispatchDragEvent(target, `dragmove`, { clientX: 300, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 300, clientY: 0 });

    // Still restrained immediately after the drag itself ends — the
    // drag's own final commit is still gated.
    const afterDragCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(afterDragCall.find(entry => entry.i === `b`)!.y).toBe(2);

    ref.current!.compactNow();

    const afterCompactNowCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(afterCompactNowCall.find(entry => entry.i === `b`)!.y).toBe(0);
  });

  it(`Should have no effect on the same scenario when restoreOnDrag is off (the default) — B rises immediately during the drag`, () => {
    const layout: TLayout = [
      { h: 2, i: `a`, w: 2, x: 0, y: 0 },
      { h: 2, i: `b`, w: 2, x: 0, y: 2 },
    ];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout layout={layout} margin={[10, 10]} onLayoutChange={handleChange} rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    dispatchDragEvent(target, `dragmove`, { clientX: 300, clientY: 0 });

    const midDragCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(midDragCall.find(entry => entry.i === `b`)!.y).toBe(0);
  });

  it(`Should use the x axis instead of y for ECompactType.HORIZONTAL`, () => {
    const layout: TLayout = [
      { h: 2, i: `a`, w: 2, x: 0, y: 0 },
      { h: 2, i: `b`, w: 2, x: 2, y: 0 },
    ];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout compactType={ECompactType.HORIZONTAL} layout={layout} margin={[10, 10]} onLayoutChange={handleChange} restoreOnDrag rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    dispatchDragEvent(target, `dragmove`, { clientX: 0, clientY: 300 });

    const midDragCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    // B should stay at its own pre-drag x:2, not shift left past it.
    expect(midDragCall.find(entry => entry.i === `b`)!.x).toBe(2);
  });

  it(`Should have no effect on a resize (only scoped to drag) — B still compacts normally, unrestricted, during a resize`, () => {
    const layout: TLayout = [
      { h: 2, i: `a`, w: 2, x: 0, y: 0 },
      { h: 2, i: `b`, w: 2, x: 0, y: 2 },
    ];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout layout={layout} margin={[10, 10]} onLayoutChange={handleChange} restoreOnDrag rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    // Resizing A shorter (not a drag at all) opens a gap above B — with
    // restoreOnDrag correctly scoped to drag only, B should still rise
    // to fill it via normal, unrestricted VERTICAL compaction, exactly
    // as if restoreOnDrag weren't set.
    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    const bottomOnly = { bottom: true, left: false, right: false, top: false };
    dispatchResizeEvent(target, `resizestart`, { edges: bottomOnly });
    dispatchResizeEvent(target, `resizemove`, { clientX: 0, clientY: -150, edges: bottomOnly });
    dispatchResizeEvent(target, `resizeend`, { clientX: 0, clientY: -150, edges: bottomOnly });

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(lastCall.find(entry => entry.i === `b`)!.y).toBe(lastCall.find(entry => entry.i === `a`)!.h);
  });
});

import { describe, expect, it, vi } from 'vitest';
import { fireEvent, render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import { dispatchDragEvent, dispatchResizeEvent, stubOffsetWidth, restoreOffsetWidth } from './test-helpers';

describe(`GridLayout onDragStart/onDragMove/onDragEnd`, () => {
  it(`Should call onDragStart/onDragMove/onDragEnd at the right gesture phases, with the dragged item's own id`, () => {
    const onDragStart = vi.fn();
    const onDragMove = vi.fn();
    const onDragEnd = vi.fn();
    const layout: TLayout = [{ h: 2, i: `a`, w: 2, x: 0, y: 0 }];
    const { container } = render(
      <GridLayout layout={layout} onDragEnd={onDragEnd} onDragMove={onDragMove} onDragStart={onDragStart}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    expect(onDragStart).toHaveBeenCalledWith(`a`);
    expect(onDragMove).not.toHaveBeenCalled();
    expect(onDragEnd).not.toHaveBeenCalled();

    dispatchDragEvent(target, `dragmove`, { clientX: 50, clientY: 0 });
    expect(onDragMove).toHaveBeenCalledWith(`a`);
    expect(onDragEnd).not.toHaveBeenCalled();

    dispatchDragEvent(target, `dragend`, { clientX: 50, clientY: 0 });
    expect(onDragEnd).toHaveBeenCalledWith(`a`);
    expect(onDragStart).toHaveBeenCalledTimes(1);
    expect(onDragMove).toHaveBeenCalledTimes(1);
    expect(onDragEnd).toHaveBeenCalledTimes(1);
  });
});

describe(`GridLayout onMoveBlockedByCollision`, () => {
  it(`Should fire when a drag is fully blocked by preventCollision`, () => {
    stubOffsetWidth(1210);
    const onMoveBlockedByCollision = vi.fn();
    // A (x:0,w:2) and B (x:2,w:2) adjacent — dragging A right into B's
    // own spot, with preventCollision on, should be fully blocked (A
    // ends up right back where it started).
    const layout: TLayout = [
      { h: 2, i: `a`, w: 2, x: 0, y: 0 },
      { h: 2, i: `b`, w: 2, x: 2, y: 0 },
    ];
    const { container } = render(
      <GridLayout colNum={12} layout={layout} margin={[10, 10]} onMoveBlockedByCollision={onMoveBlockedByCollision} preventCollision rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    // colWidth = (1210-130)/12 = 90. A landing on grid x=2 needs
    // left≈210; dragstart's own stubbed left is 5, so delta=205.
    dispatchDragEvent(target, `dragmove`, { clientX: 205, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 205, clientY: 0 });

    expect(onMoveBlockedByCollision).toHaveBeenCalledWith(`a`);
    restoreOffsetWidth();
  });

  it(`Should not fire when preventCollision is off (the collision is resolved by pushing, not blocking)`, () => {
    stubOffsetWidth(1210);
    const onMoveBlockedByCollision = vi.fn();
    const layout: TLayout = [
      { h: 2, i: `a`, w: 2, x: 0, y: 0 },
      { h: 2, i: `b`, w: 2, x: 2, y: 0 },
    ];
    const { container } = render(
      <GridLayout colNum={12} layout={layout} margin={[10, 10]} onMoveBlockedByCollision={onMoveBlockedByCollision} rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    dispatchDragEvent(target, `dragmove`, { clientX: 205, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 205, clientY: 0 });

    expect(onMoveBlockedByCollision).not.toHaveBeenCalled();
    restoreOffsetWidth();
  });

  it(`Should fire on a resize whenever preventCollision clamps the requested size at all (not just a full block)`, () => {
    stubOffsetWidth(1210);
    const onMoveBlockedByCollision = vi.fn();
    // A (x:0,w:2) resizing wider, with B (x:2,w:2) immediately to its
    // right — with preventCollision on, growing into B's own space
    // should clamp (not fully block) and still report the collision.
    const layout: TLayout = [
      { h: 2, i: `a`, w: 2, x: 0, y: 0 },
      { h: 2, i: `b`, w: 2, x: 2, y: 0 },
    ];
    const { container } = render(
      <GridLayout colNum={12} layout={layout} margin={[10, 10]} onMoveBlockedByCollision={onMoveBlockedByCollision} preventCollision rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    const eastOnly = { bottom: false, left: false, right: true, top: false };
    dispatchResizeEvent(target, `resizestart`, { edges: eastOnly });
    // Growing A's own width well past B's own starting edge.
    dispatchResizeEvent(target, `resizemove`, { clientX: 300, clientY: 0, edges: eastOnly });
    dispatchResizeEvent(target, `resizeend`, { clientX: 300, clientY: 0, edges: eastOnly });

    expect(onMoveBlockedByCollision).toHaveBeenCalledWith(`a`);
    restoreOffsetWidth();
  });
});

describe(`GridLayout onSelectionChanged`, () => {
  it(`Should not fire on initial mount`, () => {
    const onSelectionChanged = vi.fn();
    render(
      <GridLayout layout={[{ h: 2, i: `a`, w: 2, x: 0, y: 0 }]} multiSelect onSelectionChanged={onSelectionChanged}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    expect(onSelectionChanged).not.toHaveBeenCalled();
  });

  it(`Should fire with the current selection when an item is clicked (multiSelect on)`, () => {
    const onSelectionChanged = vi.fn();
    const { container } = render(
      <GridLayout layout={[{ h: 2, i: `a`, w: 2, x: 0, y: 0 }]} multiSelect onSelectionChanged={onSelectionChanged}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    fireEvent.click(target);

    expect(onSelectionChanged).toHaveBeenCalledWith([`a`]);
  });

  it(`Should not fire at all when multiSelect is off (clicking is a no-op for selection)`, () => {
    const onSelectionChanged = vi.fn();
    const { container } = render(
      <GridLayout layout={[{ h: 2, i: `a`, w: 2, x: 0, y: 0 }]} onSelectionChanged={onSelectionChanged}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    fireEvent.click(target);

    expect(onSelectionChanged).not.toHaveBeenCalled();
  });
});

import { afterEach, describe, expect, it } from 'vitest';
import { render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import { restoreOffsetWidth, stubOffsetWidth } from './test-helpers';

const basicLayout = (): TLayout => [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];

afterEach(() => {
  restoreOffsetWidth();
});

describe(`GridLayout transitionDurationMs/transitionTimingFunction`, () => {
  it(`Should apply the default 200ms/ease as CSS custom properties on the root when unset`, () => {
    const { container } = render(
      <GridLayout layout={basicLayout()}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const root = container.querySelector(`.kdl-grid-layout`) as HTMLElement;
    expect(root.style.getPropertyValue(`--kdl-transition-duration`)).toBe(`200ms`);
    expect(root.style.getPropertyValue(`--kdl-transition-timing`)).toBe(`ease`);
  });

  it(`Should apply a custom transitionDurationMs/transitionTimingFunction`, () => {
    const { container } = render(
      <GridLayout layout={basicLayout()} transitionDurationMs={500} transitionTimingFunction="linear">
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const root = container.querySelector(`.kdl-grid-layout`) as HTMLElement;
    expect(root.style.getPropertyValue(`--kdl-transition-duration`)).toBe(`500ms`);
    expect(root.style.getPropertyValue(`--kdl-transition-timing`)).toBe(`linear`);
  });
});

describe(`GridItem borderRadiusPx/useBorderRadius`, () => {
  it(`Should not apply a border radius by default (useBorderRadius off)`, () => {
    const { container } = render(
      <GridLayout layout={basicLayout()}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const item = container.querySelector(`.kdl-grid-item`) as HTMLElement;
    expect(item.style.borderRadius).toBe(``);
  });

  it(`Should apply the default 10px border radius when useBorderRadius is on grid-wide`, () => {
    const { container } = render(
      <GridLayout layout={basicLayout()} useBorderRadius>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const item = container.querySelector(`.kdl-grid-item`) as HTMLElement;
    expect(item.style.borderRadius).toBe(`10px`);
  });

  it(`Should apply a custom grid-wide borderRadiusPx`, () => {
    const { container } = render(
      <GridLayout borderRadiusPx={24} layout={basicLayout()} useBorderRadius>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const item = container.querySelector(`.kdl-grid-item`) as HTMLElement;
    expect(item.style.borderRadius).toBe(`24px`);
  });

  it(`Should let a per-item useBorderRadius override the grid-wide default in either direction`, () => {
    const layout: TLayout = [
      { h: 2, i: `0`, useBorderRadius: false, w: 2, x: 0, y: 0 },
      { h: 2, i: `1`, useBorderRadius: true, w: 2, x: 2, y: 0 },
    ];
    const { container } = render(
      <GridLayout layout={layout} useBorderRadius={false}>
        <GridItem i="0">Item 0</GridItem>
        <GridItem i="1">Item 1</GridItem>
      </GridLayout>,
    );

    const items = container.querySelectorAll(`.kdl-grid-item`);
    expect((items[0] as HTMLElement).style.borderRadius).toBe(``);
    expect((items[1] as HTMLElement).style.borderRadius).toBe(`10px`);
  });

  it(`Should let a per-item borderRadiusPx override the grid-wide value`, () => {
    const layout: TLayout = [{ borderRadiusPx: 4, h: 2, i: `0`, useBorderRadius: true, w: 2, x: 0, y: 0 }];
    const { container } = render(
      <GridLayout borderRadiusPx={10} layout={layout}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const item = container.querySelector(`.kdl-grid-item`) as HTMLElement;
    expect(item.style.borderRadius).toBe(`4px`);
  });
});

describe(`GridLayout minW-driven container width expansion`, () => {
  it(`Should apply overflowX: auto on the root when an item's own minW pushes effectiveContainerWidth past the real measured width — confirmed gap via a fresh coverage report`, () => {
    // needsHorizontalScroll ("effectiveContainerWidth > containerWidth")
    // — no existing test in this package specifically asserts the root
    // element's own overflowX style value under this condition, only
    // effectiveContainerWidth's own downstream effects elsewhere (item
    // pixel width, etc). A narrow measured container (100px) combined
    // with a large minW (10, at the default rowHeight:150 floors to
    // 10*150+9*10=1590px) reliably triggers the expansion.
    stubOffsetWidth(100);
    const layout: TLayout = [{ h: 2, i: `0`, minW: 10, w: 2, x: 0, y: 0 }];
    const { container } = render(
      <GridLayout layout={layout}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const root = container.querySelector(`.kdl-grid-layout`) as HTMLElement;
    expect(root.style.overflowX).toBe(`auto`);
  });

  it(`Should fall back to a plain 'auto' height on the inner width-wrapper when containerHeight itself is undefined (heightMode: 'fixed') — confirmed gap via a fresh coverage report`, () => {
    // The inner width-wrapper's own "containerHeight ?? 'auto'" style
    // fallback — only reachable when needsWidthWrapper is true (same
    // minW-driven expansion as the test above) *and* containerHeight
    // itself resolves to undefined, which only happens for
    // heightMode: 'fixed' (the default 'auto' mode always computes a
    // real pixel value instead).
    stubOffsetWidth(100);
    const layout: TLayout = [{ h: 2, i: `0`, minW: 10, w: 2, x: 0, y: 0 }];
    const { container } = render(
      <GridLayout heightMode="fixed" layout={layout}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const root = container.querySelector(`.kdl-grid-layout`) as HTMLElement;
    expect(root.style.height).toBe(``);
    const wrapper = root.firstElementChild as HTMLElement;
    expect(wrapper.style.height).toBe(`auto`);
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import { dispatchDragEvent, dispatchResizeEvent, restoreOffsetWidth, stubOffsetWidth } from './test-helpers';

/**
 * jsdom applies no real CSS transforms/layout at all, so there's no way
 * to render a genuinely scaled ancestor and observe the browser's own
 * rendering — the same limitation this suite's own RTL (Phase 7) tests
 * work around. Instead, these tests verify the arithmetic directly:
 * with a stubbed `containerWidth` (via `stubOffsetWidth`) producing a
 * known `colWidth`, a hand-computed raw pointer delta produces a
 * specific, hand-computed grid-unit result at `transformScale={1}`,
 * and a *different*, also hand-computed result at other scale values
 * — confirming the delta is actually divided by `transformScale`
 * before being applied, not just that *something* changed.
 */
describe(`GridLayout transformScale`, () => {
  afterEach(() => {
    restoreOffsetWidth();
  });

  it(`Should not affect drag math at all when left at the default (1)`, () => {
    // colNum=20 (wide enough that clamping to the grid's own right edge
    // never interferes with the numbers below) at containerWidth=2010,
    // margin=[10,10] — colWidth = (2010 - 10*21)/20 = 90.
    stubOffsetWidth(2010);
    const layout: TLayout = [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout colNum={20} layout={layout} margin={[10, 10]} onLayoutChange={handleChange} rowHeight={100}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`.kdl-grid-item`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    // dispatchDragEvent's own stub fixes the item's own dragstart
    // position at left:5 (via a stubbed getBoundingClientRect) — a raw
    // 1005px pointer delta from there lands at left:1010, which
    // converts to grid x = round((1010-10)/(90+10)) = 10.
    dispatchDragEvent(target, `dragmove`, { clientX: 1005, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 1005, clientY: 0 });

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(lastCall.find(entry => entry.i === `0`)!.x).toBe(10);
  });

  it(`Should halve the effective drag distance at transformScale=2`, () => {
    stubOffsetWidth(2010);
    const layout: TLayout = [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout colNum={20} layout={layout} margin={[10, 10]} onLayoutChange={handleChange} rowHeight={100} transformScale={2}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`.kdl-grid-item`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    // Same raw 1005px pointer delta as the scale=1 test above, but
    // divided by transformScale=2 first: 1005/2=502.5, landing at
    // left:5+502.5=507.5 -> grid x = round((507.5-10)/100) = 5, half
    // of the scale=1 test's own result (10), not the same value.
    dispatchDragEvent(target, `dragmove`, { clientX: 1005, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 1005, clientY: 0 });

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(lastCall.find(entry => entry.i === `0`)!.x).toBe(5);
  });

  it(`Should double the effective drag distance at transformScale=0.5`, () => {
    stubOffsetWidth(2010);
    const layout: TLayout = [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout colNum={20} layout={layout} margin={[10, 10]} onLayoutChange={handleChange} rowHeight={100} transformScale={0.5}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`.kdl-grid-item`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    // 1005/0.5 = 2010 -> left:5+2010=2015 -> grid x = round((2015-10)/100)
    // = round(20.05) = 20, clamped to colNum-w = 18 (the point of this
    // test is confirming the *pre-clamp* value roughly doubled, not
    // that clamping itself changed — 18 here is the grid's own bound,
    // reached specifically *because* the scale-compensated delta is
    // large enough to exceed it, unlike the scale=1/2 cases above).
    dispatchDragEvent(target, `dragmove`, { clientX: 1005, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 1005, clientY: 0 });

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(lastCall.find(entry => entry.i === `0`)!.x).toBe(18);
  });

  it(`Should scale resize deltas the same way`, () => {
    stubOffsetWidth(2010);
    const layout: TLayout = [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout colNum={20} layout={layout} margin={[10, 10]} onLayoutChange={handleChange} rowHeight={100} transformScale={2}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`.kdl-grid-item`) as HTMLElement;
    const seOnly = { bottom: true, left: false, right: true, top: false };
    dispatchResizeEvent(target, `resizestart`, { edges: seOnly });
    // resizestart's own width is 190px (calcPosition(0,0,2,2) with
    // colWidth=90,margin=10: round(90*2+10)=190). A raw 1005px delta,
    // divided by transformScale=2 first (502.5), lands at
    // 190+502.5=692.5 -> w = round((692.5+10)/100) = round(7.025) = 7.
    dispatchResizeEvent(target, `resizemove`, { clientX: 1005, clientY: 0, edges: seOnly });
    dispatchResizeEvent(target, `resizeend`, { clientX: 1005, clientY: 0, edges: seOnly });

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    expect(lastCall.find(entry => entry.i === `0`)!.w).toBe(7);
  });
});

