import { createRef } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import { ECompactType } from '@keystone-dashboard-layout/core';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import type { IGridLayoutHandle } from '../grid-layout-handle.interface';

describe(`GridLayout imperative handle`, () => {
  describe(`compactNow / rearrange`, () => {
    it(`Should compact a layout with a gap when compactNow is called`, () => {
      const handleChange = vi.fn();
      const ref = createRef<IGridLayoutHandle>();
      const layout: TLayout = [
        { h: 2, i: `0`, w: 2, x: 0, y: 0 },
        { h: 2, i: `1`, w: 2, x: 0, y: 5 },
      ];
      render(
        <GridLayout compactType={ECompactType.VERTICAL} layout={layout} onLayoutChange={handleChange} ref={ref}>
          <GridItem i="0">Item 0</GridItem>
          <GridItem i="1">Item 1</GridItem>
        </GridLayout>,
      );

      ref.current!.compactNow();

      const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
      expect(lastCall.find(entry => entry.i === `1`)!.y).toBe(2);
    });

    it(`Should still tidy up when compactType is NONE — a manual "tidy up" always tidies up, regardless of the ambient auto-compact setting`, () => {
      const handleChange = vi.fn();
      const ref = createRef<IGridLayoutHandle>();
      const layout: TLayout = [
        { h: 2, i: `0`, w: 2, x: 0, y: 0 },
        { h: 2, i: `1`, w: 2, x: 0, y: 5 },
      ];
      render(
        <GridLayout compactType={ECompactType.NONE} layout={layout} onLayoutChange={handleChange} ref={ref}>
          <GridItem i="0">Item 0</GridItem>
          <GridItem i="1">Item 1</GridItem>
        </GridLayout>,
      );

      ref.current!.compactNow();

      const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
      expect(lastCall.find(entry => entry.i === `1`)!.y).toBe(2);
    });

    it(`rearrange() should be an alias for compactNow()`, () => {
      const handleChange = vi.fn();
      const ref = createRef<IGridLayoutHandle>();
      const layout: TLayout = [
        { h: 2, i: `0`, w: 2, x: 0, y: 0 },
        { h: 2, i: `1`, w: 2, x: 0, y: 5 },
      ];
      render(
        <GridLayout layout={layout} onLayoutChange={handleChange} ref={ref}>
          <GridItem i="0">Item 0</GridItem>
          <GridItem i="1">Item 1</GridItem>
        </GridLayout>,
      );

      ref.current!.rearrange();

      const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
      expect(lastCall.find(entry => entry.i === `1`)!.y).toBe(2);
    });
  });

  describe(`duplicateItem`, () => {
    it(`Should clone the item with a new, collision-safe id, placed below the source`, () => {
      const handleChange = vi.fn();
      const ref = createRef<IGridLayoutHandle>();
      const layout: TLayout = [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];
      render(
        <GridLayout compactType={ECompactType.NONE} layout={layout} onLayoutChange={handleChange} ref={ref}>
          <GridItem i="0">Item 0</GridItem>
        </GridLayout>,
      );

      const newId = ref.current!.duplicateItem(`0`);

      expect(newId).toBe(`0-copy`);
      const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
      const copy = lastCall.find(entry => entry.i === `0-copy`);
      expect(copy).toBeTruthy();
      expect(copy!.w).toBe(2);
      expect(copy!.h).toBe(2);
      expect(copy!.x).toBe(0);
    });

    it(`Should not carry over the source item's own moved flag`, () => {
      const handleChange = vi.fn();
      const ref = createRef<IGridLayoutHandle>();
      const layout: TLayout = [{ h: 2, i: `0`, moved: true, w: 2, x: 0, y: 0 }];
      render(
        <GridLayout compactType={ECompactType.NONE} layout={layout} onLayoutChange={handleChange} ref={ref}>
          <GridItem i="0">Item 0</GridItem>
        </GridLayout>,
      );

      ref.current!.duplicateItem(`0`);

      const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
      const copy = lastCall.find(entry => entry.i === `0-copy`);
      expect(copy!.moved).not.toBe(true);
    });

    it(`Should generate a further-suffixed id when a previous copy already exists`, () => {
      const handleChange = vi.fn();
      const ref = createRef<IGridLayoutHandle>();
      const layout: TLayout = [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];
      const { rerender } = render(
        <GridLayout compactType={ECompactType.NONE} layout={layout} onLayoutChange={handleChange} ref={ref}>
          <GridItem i="0">Item 0</GridItem>
        </GridLayout>,
      );

      const firstCopyId = ref.current!.duplicateItem(`0`);
      const afterFirst = handleChange.mock.calls.at(-1)![0] as TLayout;
      rerender(
        <GridLayout compactType={ECompactType.NONE} layout={afterFirst} onLayoutChange={handleChange} ref={ref}>
          <GridItem i="0">Item 0</GridItem>
          <GridItem i="0-copy">Item 0 copy</GridItem>
        </GridLayout>,
      );

      const secondCopyId = ref.current!.duplicateItem(`0`);

      expect(firstCopyId).toBe(`0-copy`);
      expect(secondCopyId).toBe(`0-copy-2`);
    });

    it(`Should return null when the id doesn't match any item currently in the layout`, () => {
      const ref = createRef<IGridLayoutHandle>();
      render(
        <GridLayout layout={[{ h: 2, i: `0`, w: 2, x: 0, y: 0 }]} ref={ref}>
          <GridItem i="0">Item 0</GridItem>
        </GridLayout>,
      );

      expect(ref.current!.duplicateItem(`does-not-exist`)).toBeNull();
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';

/**
 * `createNativeAutoScroll()` drives a real, `requestAnimationFrame`-based
 * scrolling engine — rather than trying to observe its actual scrolling
 * behavior (which the Vue package's own test suite doesn't attempt
 * either, per that composable's own doc comment: "no test in this suite
 * currently exercises autoScroll's own scrolling behavior directly"),
 * this mocks the factory itself so these tests can assert on *when*
 * `start`/`update`/`stop` get called — the actual behavioral contract
 * `useGridItemDrag.ts`/`useGridItemResize.ts` are responsible for, as
 * opposed to the scrolling engine's own internals (already covered by
 * `core`'s own test suite). `mockAutoScrollSpies` (not e.g.
 * `autoScrollSpies`) — the `mock` prefix is required by Vitest's own
 * hoisting-safety check for referencing an outer variable from inside a
 * `vi.mock` factory.
 */
const mockAutoScrollSpies = { start: vi.fn(), stop: vi.fn(), update: vi.fn() };

vi.mock(`@keystone-dashboard-layout/core`, async importOriginal => {
  const actual = await importOriginal<typeof import('@keystone-dashboard-layout/core')>();
  return {
    ...actual,
    createNativeAutoScroll: vi.fn(() => mockAutoScrollSpies),
  };
});

import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import { dispatchDragEvent, dispatchResizeEvent, restoreOffsetWidth, stubOffsetWidth } from './test-helpers';

const basicLayout = (): TLayout => [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];

describe(`GridLayout autoScroll`, () => {
  beforeEach(() => {
    mockAutoScrollSpies.start.mockClear();
    mockAutoScrollSpies.update.mockClear();
    mockAutoScrollSpies.stop.mockClear();
  });

  afterEach(() => {
    restoreOffsetWidth();
  });

  it(`Should not call start/update at all when autoScroll is off (the default) — stop() itself is still called defensively regardless, matching Vue's own unconditional "safe no-op if never started" pattern on dragend/resizeend`, () => {
    const { container } = render(
      <GridLayout layout={basicLayout()}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="0"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    dispatchDragEvent(target, `dragmove`, { clientX: 50, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 50, clientY: 0 });

    expect(mockAutoScrollSpies.start).not.toHaveBeenCalled();
    expect(mockAutoScrollSpies.update).not.toHaveBeenCalled();
  });

  it(`Should start on dragstart, update on dragmove, and stop on dragend when enabled`, () => {
    const { container } = render(
      <GridLayout autoScroll layout={basicLayout()}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="0"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    expect(mockAutoScrollSpies.start).toHaveBeenCalledTimes(1);
    expect(mockAutoScrollSpies.stop).not.toHaveBeenCalled();

    dispatchDragEvent(target, `dragmove`, { clientX: 50, clientY: 0 });
    expect(mockAutoScrollSpies.update).toHaveBeenCalledTimes(1);

    dispatchDragEvent(target, `dragend`, { clientX: 50, clientY: 0 });
    expect(mockAutoScrollSpies.stop).toHaveBeenCalledTimes(1);
  });

  it(`Should start on resizestart, update on resizemove, and stop on resizeend when enabled`, () => {
    const { container } = render(
      <GridLayout autoScroll layout={basicLayout()}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="0"]`) as HTMLElement;
    dispatchResizeEvent(target, `resizestart`);
    expect(mockAutoScrollSpies.start).toHaveBeenCalledTimes(1);

    dispatchResizeEvent(target, `resizemove`, { clientX: 50, clientY: 0 });
    expect(mockAutoScrollSpies.update).toHaveBeenCalledTimes(1);

    dispatchResizeEvent(target, `resizeend`, { clientX: 50, clientY: 0 });
    expect(mockAutoScrollSpies.stop).toHaveBeenCalledTimes(1);
  });

  it(`Should respect a per-item override that disables autoScroll even when the grid-wide default is on`, () => {
    const layout: TLayout = [{ autoScroll: false, h: 2, i: `0`, w: 2, x: 0, y: 0 }];
    const { container } = render(
      <GridLayout autoScroll layout={layout}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="0"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);

    expect(mockAutoScrollSpies.start).not.toHaveBeenCalled();
  });

  it(`Should respect a per-item override that enables autoScroll even when the grid-wide default is off`, () => {
    const layout: TLayout = [{ autoScroll: true, h: 2, i: `0`, w: 2, x: 0, y: 0 }];
    const { container } = render(
      <GridLayout layout={layout}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="0"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);

    expect(mockAutoScrollSpies.start).toHaveBeenCalledTimes(1);
  });
});

import { describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import { restoreOffsetWidth, stubOffsetWidth, triggerResize } from './test-helpers';

describe(`GridLayout onLayoutReady`, () => {
  it(`Should call onLayoutReady exactly once, after the first successful container-width measurement, with the current layout`, () => {
    stubOffsetWidth(1210);
    const onLayoutReady = vi.fn();
    const layout: TLayout = [{ h: 2, i: `a`, w: 2, x: 0, y: 0 }];
    render(
      <GridLayout layout={layout} onLayoutReady={onLayoutReady}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    expect(onLayoutReady).toHaveBeenCalledTimes(1);
    const readyLayout = onLayoutReady.mock.calls[0][0] as TLayout;
    expect(readyLayout.find(entry => entry.i === `a`)).toBeTruthy();
    restoreOffsetWidth();
  });

  it(`Should not call onLayoutReady again on a later container resize`, () => {
    stubOffsetWidth(1210);
    const onLayoutReady = vi.fn();
    render(
      <GridLayout layout={[{ h: 2, i: `a`, w: 2, x: 0, y: 0 }]} onLayoutReady={onLayoutReady}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );
    expect(onLayoutReady).toHaveBeenCalledTimes(1);

    triggerResize(600);
    expect(onLayoutReady).toHaveBeenCalledTimes(1);
    restoreOffsetWidth();
  });
});

describe(`GridLayout onColumnsChanged`, () => {
  it(`Should not fire on initial mount`, () => {
    const onColumnsChanged = vi.fn();
    render(
      <GridLayout colNum={12} layout={[{ h: 2, i: `a`, w: 2, x: 0, y: 0 }]} onColumnsChanged={onColumnsChanged}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    expect(onColumnsChanged).not.toHaveBeenCalled();
  });

  it(`Should fire with the new value when the colNum prop itself changes`, () => {
    const onColumnsChanged = vi.fn();
    const layout: TLayout = [{ h: 2, i: `a`, w: 2, x: 0, y: 0 }];
    const { rerender } = render(
      <GridLayout colNum={12} layout={layout} onColumnsChanged={onColumnsChanged}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    rerender(
      <GridLayout colNum={6} layout={layout} onColumnsChanged={onColumnsChanged}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    expect(onColumnsChanged).toHaveBeenCalledWith(6);
    expect(onColumnsChanged).toHaveBeenCalledTimes(1);
  });

  it(`Should not fire from a responsive breakpoint change alone (that's onBreakpointChange's own scope, not colNum the prop)`, () => {
    stubOffsetWidth(1210);
    const onColumnsChanged = vi.fn();
    const onBreakpointChange = vi.fn();
    render(
      <GridLayout layout={[{ h: 2, i: `a`, w: 2, x: 0, y: 0 }]} onBreakpointChange={onBreakpointChange} onColumnsChanged={onColumnsChanged} responsive>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    triggerResize(500);

    expect(onBreakpointChange).toHaveBeenCalled();
    expect(onColumnsChanged).not.toHaveBeenCalled();
    restoreOffsetWidth();
  });

  // Confirmed gap via a fresh mutation run: every test above always
  // provides onColumnsChanged, so a mutant removing the `?.` entirely
  // (calling it directly) never actually gets exercised in a scenario
  // where it's `undefined` -- which would throw, but only if some test
  // changes colNum without providing the callback at all.
  it(`Should not throw when colNum changes and onColumnsChanged isn't provided`, () => {
    const layout: TLayout = [{ h: 2, i: `a`, w: 2, x: 0, y: 0 }];
    const { rerender } = render(
      <GridLayout colNum={12} layout={layout}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    expect(() => rerender(
      <GridLayout colNum={6} layout={layout}>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    )).not.toThrow();
  });
});

import { createRef } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import type { IGridLayoutHandle } from '../grid-layout-handle.interface';

describe(`GridLayout scrollToItem/focusItem`, () => {
  const buildLayout = (): TLayout => [
    { h: 2, i: `a`, w: 2, x: 0, y: 0 },
    { h: 2, i: `b`, w: 2, x: 2, y: 0 },
  ];

  it(`Should scroll the matching item's own element into view`, async () => {
    const ref = createRef<IGridLayoutHandle>();
    const { container } = render(
      <GridLayout layout={buildLayout()} ref={ref}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="b"]`) as HTMLElement;
    const scrollIntoViewSpy = vi.fn();
    target.scrollIntoView = scrollIntoViewSpy;

    await ref.current!.scrollToItem(`b`);

    expect(scrollIntoViewSpy).toHaveBeenCalledWith({ behavior: `smooth`, block: `nearest`, inline: `nearest` });
  });

  it(`Should be a no-op (not throw) when scrollToItem is called with an id that doesn't match any rendered item`, async () => {
    const ref = createRef<IGridLayoutHandle>();
    render(
      <GridLayout layout={buildLayout()} ref={ref}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    await expect(ref.current!.scrollToItem(`does-not-exist`)).resolves.toBeUndefined();
  });

  it(`Should move keyboard focus to the matching item's own element`, async () => {
    const ref = createRef<IGridLayoutHandle>();
    const { container } = render(
      <GridLayout layout={buildLayout()} ref={ref}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    await ref.current!.focusItem(`b`);

    const target = container.querySelector(`[data-grid-item-id="b"]`) as HTMLElement;
    expect(document.activeElement).toBe(target);
  });

  it(`Should be a no-op (not throw) when focusItem is called with an id that doesn't match any rendered item`, async () => {
    const ref = createRef<IGridLayoutHandle>();
    render(
      <GridLayout layout={buildLayout()} ref={ref}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    await expect(ref.current!.focusItem(`does-not-exist`)).resolves.toBeUndefined();
  });

  it(`Should scope the lookup to this grid's own container (not a global document query)`, async () => {
    // Two GridLayout instances, each with an item sharing the same id
    // ('shared') — scrollToItem on the *second* grid's own ref should
    // only ever touch that grid's own element, never the first's.
    const refA = createRef<IGridLayoutHandle>();
    const refB = createRef<IGridLayoutHandle>();
    render(
      <>
        <GridLayout layout={[{ h: 2, i: `shared`, w: 2, x: 0, y: 0 }]} ref={refA}>
          <GridItem i="shared">Grid A's shared item</GridItem>
        </GridLayout>
        <GridLayout layout={[{ h: 2, i: `shared`, w: 2, x: 0, y: 0 }]} ref={refB}>
          <GridItem i="shared">Grid B's shared item</GridItem>
        </GridLayout>
      </>,
    );

    const allSharedElements = document.querySelectorAll(`[data-grid-item-id="shared"]`);
    expect(allSharedElements.length).toBe(2);
    const [elementInA, elementInB] = Array.from(allSharedElements) as HTMLElement[];
    const scrollSpyA = vi.fn();
    const scrollSpyB = vi.fn();
    elementInA.scrollIntoView = scrollSpyA;
    elementInB.scrollIntoView = scrollSpyB;

    await refB.current!.scrollToItem(`shared`);

    expect(scrollSpyB).toHaveBeenCalledTimes(1);
    expect(scrollSpyA).not.toHaveBeenCalled();
  });
});

