import { describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import { dispatchDragEvent, restoreOffsetWidth, stubOffsetWidth } from './test-helpers';

describe(`GridLayout horizontalShift`, () => {
  // A (w:2,x:0) and B (w:2,x:2) start adjacent, touching but not
  // overlapping — dragging A right by exactly 2 grid units lands it
  // squarely on B's own original spot (a full-overlap collision), and
  // vacates A's own starting spot entirely. h:1 (not 2) on both is
  // deliberate: it keeps whichever direction B ends up pushed in from
  // re-colliding with A's own new position in either scenario below —
  // a *second*, cascading collision would exercise a separate,
  // pre-existing argument-order bug in `moveElementAwayFromCollision`'s
  // own recursive call (unrelated to `horizontalShift` being wired up
  // correctly, and out of scope for this phase — flagged separately in
  // the docs), so this geometry is chosen specifically to stay clear
  // of it and isolate the one thing this test actually needs to check.
  const buildLayout = (): TLayout => [
    { h: 1, i: `a`, w: 2, x: 0, y: 0 },
    { h: 1, i: `b`, w: 2, x: 2, y: 0 },
  ];

  it(`Should push the collided-with item straight down by default (horizontalShift off)`, () => {
    stubOffsetWidth(1210);
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout colNum={12} layout={buildLayout()} margin={[10, 10]} onLayoutChange={handleChange} rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    // colWidth = (1210-130)/12 = 90. Landing at grid x=2 needs
    // left ≈ 210 (round((210-10)/100)=2); dragstart's own stubbed left
    // is 5, so a clientX delta of 205 lands there.
    dispatchDragEvent(target, `dragmove`, { clientX: 205, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 205, clientY: 0 });

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    const b = lastCall.find(entry => entry.i === `b`)!;
    expect(b.x).toBe(2);
    expect(b.y).toBe(1);
    restoreOffsetWidth();
  });

  it(`Should push the collided-with item horizontally instead, when horizontalShift is on`, () => {
    stubOffsetWidth(1210);
    const handleChange = vi.fn();
    const { container } = render(
      <GridLayout colNum={12} horizontalShift layout={buildLayout()} margin={[10, 10]} onLayoutChange={handleChange} rowHeight={100}>
        <GridItem i="a">A</GridItem>
        <GridItem i="b">B</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="a"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    dispatchDragEvent(target, `dragmove`, { clientX: 205, clientY: 0 });
    dispatchDragEvent(target, `dragend`, { clientX: 205, clientY: 0 });

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    const b = lastCall.find(entry => entry.i === `b`)!;
    // Pushed left by A's own width (2), into A's now-vacated spot,
    // staying on the same row — distinctly different from the
    // vertical-push default above.
    expect(b.x).toBe(0);
    expect(b.y).toBe(0);
    restoreOffsetWidth();
  });
});

import { createRef } from 'react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import type { ICompactor, TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import type { IGridLayoutHandle } from '../grid-layout-handle.interface';
import { dispatchDragEvent, restoreOffsetWidth, stubOffsetWidth } from './test-helpers';

describe(`GridLayout compactor`, () => {
  afterEach(() => {
    restoreOffsetWidth();
  });

  it(`Should use a custom compactor instead of the built-in strategy when provided`, () => {
    stubOffsetWidth(1200);
    const handleChange = vi.fn();
    // A deliberately unrealistic strategy (moves everything to x:0) so
    // there's no ambiguity about whether it — rather than the default
    // VERTICAL compactor — actually ran.
    const shelfCompactor: ICompactor = {
      compact: (layout: TLayout): TLayout => layout.map(item => ({ ...item, x: 0 })),
      type: `shelf`,
    };
    const layout: TLayout = [{ h: 2, i: `0`, w: 2, x: 5, y: 0 }];
    const { container } = render(
      <GridLayout compactor={shelfCompactor} layout={layout} margin={[10, 10]} onLayoutChange={handleChange} rowHeight={100}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const target = container.querySelector(`[data-grid-item-id="0"]`) as HTMLElement;
    dispatchDragEvent(target, `dragstart`);
    dispatchDragEvent(target, `dragmove`, { clientX: 0, clientY: 200 });
    dispatchDragEvent(target, `dragend`, { clientX: 0, clientY: 200 });

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    // The custom compactor forces x:0 on every commit, regardless of
    // where the drag itself tried to move the item.
    expect(lastCall.find(entry => entry.i === `0`)!.x).toBe(0);
  });
});

describe(`GridLayout exportLayoutAsSvg`, () => {
  afterEach(() => {
    restoreOffsetWidth();
  });

  it(`Should render the current layout as an SVG string, pre-filled with this grid's own dimensions`, () => {
    // stubOffsetWidth is required here even though this test doesn't
    // drag/resize anything — exportLayoutAsSvg() reads the *measured*
    // containerWidth, and the unstubbed jsdom default (falling back to
    // GridLayout's own 100px seed value) combined with the default
    // colNum:12/margin:10 produces a *negative* colWidth
    // ((100 - 13*10)/12), which core's own validation correctly rejects.
    stubOffsetWidth(1200);
    const ref = createRef<IGridLayoutHandle>();
    const layout: TLayout = [{ h: 2, i: `widget-a`, w: 2, x: 0, y: 0 }];
    render(
      <GridLayout layout={layout} ref={ref}>
        <GridItem i="widget-a">Widget A</GridItem>
      </GridLayout>,
    );

    const svg = ref.current!.exportLayoutAsSvg();

    expect(svg).toContain(`<svg`);
    expect(svg).toContain(`widget-a`);
  });

  it(`Should let an explicit option override the pre-filled grid dimension`, () => {
    stubOffsetWidth(1200);
    const ref = createRef<IGridLayoutHandle>();
    const layout: TLayout = [{ h: 2, i: `0`, w: 2, x: 0, y: 0 }];
    render(
      <GridLayout colNum={12} layout={layout} ref={ref}>
        <GridItem i="0">Item 0</GridItem>
      </GridLayout>,
    );

    const svg = ref.current!.exportLayoutAsSvg({ containerWidth: 2000 });

    expect(svg).toContain(`width="2000"`);
  });
});

import { describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import { restoreOffsetWidth, stubOffsetWidth, triggerResize } from './test-helpers';

/**
 * Regression test for a real bug found while writing the
 * `distributeEvenly` tests: `containerWidth`'s own seed default (100)
 * is indistinguishable from a genuine measurement, so on a mount with
 * `responsive` already `true`, the responsive-breakpoint effect used
 * to run once against that seed value before the real measurement
 * landed — at 100px, `getBreakpointFromWidth` resolves to `'xxs'`
 * (threshold 0), meaning every real consumer briefly saw their layout
 * bounds-corrected/compacted for a 2-column grid on every single mount,
 * regardless of the actual container size.
 */
describe(`GridLayout responsive — no spurious pre-measurement breakpoint resolution`, () => {
  it(`Should never bounds-correct against the containerWidth seed default before a real measurement lands`, () => {
    // A real, wide container (colNum would resolve to 'lg', cols=12) —
    // if the bug were present, 'a' (x:8,w:2, fits fine at cols=12)
    // would still have been clamped for a transient cols=2 pass first.
    stubOffsetWidth(1210);
    const handleChange = vi.fn();
    render(
      <GridLayout layout={[{ h: 2, i: `a`, w: 2, x: 8, y: 0 }]} onLayoutChange={handleChange} responsive>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    // Every onLayoutChange call across the whole settle process (not
    // just the last one) should already reflect the real, final
    // breakpoint's own bounds — none of them should ever show 'a'
    // clamped down to fit a 2-column grid it was never actually
    // measured at.
    handleChange.mock.calls.forEach(call => {
      const layout = call[0] as TLayout;
      const a = layout.find(entry => entry.i === `a`)!;
      expect(a.x).toBe(8);
    });
    restoreOffsetWidth();
  });

  it(`Should still resolve the correct breakpoint once the real measurement lands`, () => {
    stubOffsetWidth(1210);
    const handleChange = vi.fn();
    render(
      <GridLayout layout={[{ h: 2, i: `a`, w: 2, x: 8, y: 0 }]} onLayoutChange={handleChange} responsive>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    // 1210px is squarely within 'lg' (threshold 1200, cols=12) — 'a'
    // (x:8,w:2) fits fine there, so no correction should ever have
    // been needed at all, and onLayoutChange may not even have fired
    // yet by this point if nothing needed correcting.
    if(handleChange.mock.calls.length > 0) {
      const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
      const a = lastCall.find(entry => entry.i === `a`)!;
      expect(a.x).toBe(8);
    }

    // Now shrink to a width that genuinely needs correcting ('xs',
    // cols=4) — confirms the responsive effect still works correctly
    // once a real measurement is in play, not just that it stays
    // silent.
    triggerResize(500);

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    const a = lastCall.find(entry => entry.i === `a`)!;
    expect(a.x).toBe(2);
    restoreOffsetWidth();
  });
});

import { describe, expect, it, vi } from 'vitest';
import { render } from '@testing-library/react';
import type { TLayout } from '@keystone-dashboard-layout/core';
import { GridLayout } from '../GridLayout';
import { GridItem } from '../GridItem';
import { restoreOffsetWidth, stubOffsetWidth, triggerResize } from './test-helpers';

describe(`GridLayout distributeEvenly`, () => {
  // A static item at x:0-2,y:0-1 (h:1) blocks vertical compaction from
  // pulling a redistributed item at x:0,y:1 back up to y:0 afterward —
  // without this, the distribute-evenly wrap-to-next-row effect would
  // be invisible by the time compaction (which always runs after
  // correctBounds) finishes, since nothing else would stop the item
  // rising straight back to y:0.
  const buildLayout = (): TLayout => [
    { h: 1, i: `static`, isStatic: true, w: 2, x: 0, y: 0 },
    { h: 2, i: `a`, w: 2, x: 8, y: 0 },
  ];

  it(`Should clamp an out-of-bounds item to the right edge on a breakpoint change by default (distributeEvenly off)`, () => {
    stubOffsetWidth(1210);
    const handleChange = vi.fn();
    render(
      <GridLayout layout={buildLayout()} onLayoutChange={handleChange} responsive>
        <GridItem i="static">Static</GridItem>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    // Default breakpoints/cols: 'xs' applies from 480px width (its own
    // threshold) up to just under 768px ('sm'); at 400px, *below* that
    // 480px threshold, the applicable breakpoint is actually 'xxs'
    // (threshold 0, cols=2) instead — 500px lands squarely inside 'xs'
    // (cols=4) instead, avoiding that off-by-one-breakpoint mistake.
    // 'a' (x:8,w:2) no longer fits at cols=4 (8+2=10 > 4).
    triggerResize(500);

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    const a = lastCall.find(entry => entry.i === `a`)!;
    expect(a.x).toBe(2);
    expect(a.y).toBe(0);
    restoreOffsetWidth();
  });

  it(`Should wrap an out-of-bounds item to the next row instead of clamping, when distributeEvenly is on`, () => {
    stubOffsetWidth(1210);
    const handleChange = vi.fn();
    render(
      <GridLayout distributeEvenly layout={buildLayout()} onLayoutChange={handleChange} responsive>
        <GridItem i="static">Static</GridItem>
        <GridItem i="a">A</GridItem>
      </GridLayout>,
    );

    triggerResize(500);

    const lastCall = handleChange.mock.calls.at(-1)![0] as TLayout;
    const a = lastCall.find(entry => entry.i === `a`)!;
    expect(a.x).toBe(0);
    expect(a.y).toBe(1);
    restoreOffsetWidth();
  });
});
